assert.v:
pm.test('C1: ma phai duoc tim thay (khong 404)', function () {
    pm.expect(pm.response.code).to.not.eql(404);
});

pm.test('Giam gia khong duoc am', function () {
    pm.expect(J().discount_amount, 'giam gia am -> khach phai tra nhieu hon gia goc').to.be.at.least(0);
});

pm.test('Giam gia khong duoc vuot qua tong don', function () {
    pm.expect(J().discount_amount).to.be.at.most(500000);
});

pm.test('So tien phai tra khong duoc lon hon gia goc', function () {
    pm.expect(J().final_amount, 'final_amount > total_amount').to.be.at.most(500000);
});

pm.test('final_amount + discount_amount = total_amount', function () {
    var b = J();
    pm.expect(b.final_amount + b.discount_amount).to.eql(700000);
});

pm.test('Neu chap nhan thi ket qua phai la so nguyen an toan', function () {
    if (pm.response.code !== 200) { return; }
    var b = J();
    pm.expect(Number.isSafeInteger(b.final_amount), 'final_amount vuot khoang so nguyen an toan').to.be.true;
    pm.expect(Number.isSafeInteger(b.discount_amount)).to.be.true;
});

pm.test('Khong co truong nao ngoai hop dong API', function () {
    var allowed = ['success', 'coupon_id', 'discount_amount', 'final_amount', 'message'];
    var extra = Object.keys(J()).filter(function (k) { return allowed.indexOf(k) === -1; });
    pm.expect(extra, 'truong thua: ' + extra.join(', ')).to.be.an('array').that.is.empty;
});
